import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String customerId = req.getParameter("customer_id");
        String sortCol = req.getParameter("sort");

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against allowed values
        if (!reportType.matches("^(sales|inventory|returns)$")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build query - sort column is user-controlled for flexible reporting
        String baseQuery = "SELECT id, product_name, quantity, price, transaction_date " +
                          "FROM " + reportType + "_report " +
                          "WHERE transaction_date BETWEEN ? AND ?";

        if (customerId != null && !customerId.isEmpty()) {
            // customerId is parameterized - safe
            baseQuery += " AND customer_id = ?";
        }

        if (sortCol != null && !sortCol.isEmpty()) {
            // ORDER BY cannot be parameterized in JDBC PreparedStatement
            // We allow dynamic sorting for the reporting UI
            baseQuery += " ORDER BY " + sortCol;
        }

        log.info("Executing report query for type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(baseQuery)) {

            stmt.setString(1, startDate);
            stmt.setString(2, endDate);

            if (customerId != null && !customerId.isEmpty()) {
                stmt.setString(3, customerId);
            }

            try (ResultSet rs = stmt.executeQuery()) {
                resp.setContentType("application/json");
                PrintWriter out = resp.getWriter();
                out.print("[\n");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.print(",\n");
                    first = false;
                    out.printf("{\"id\":%d,\"product\":\"%s\",\"qty\":%d,\"price\":%.2f,\"date\":\"%s\"}",
                        rs.getInt("id"),
                        rs.getString("product_name").replace("\"", "\\\""),
                        rs.getInt("quantity"),
                        rs.getDouble("price"),
                        rs.getString("transaction_date"));
                }
                out.print("\n]");
            }
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST used for scheduled report generation - delegates to GET logic
        doGet(req, resp);
    }
}
